-- MySQL 8 / H2 MySQL mode。版本进入唯一键，保留历史计算结果。
CREATE TABLE IF NOT EXISTS category(id BIGINT PRIMARY KEY,name VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS supplier(id BIGINT PRIMARY KEY,name VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS product(id BIGINT PRIMARY KEY,name VARCHAR(255) NOT NULL,category_id BIGINT NOT NULL,supplier_id BIGINT,scenario VARCHAR(16),status INT DEFAULT 1,FOREIGN KEY(category_id) REFERENCES category(id),FOREIGN KEY(supplier_id) REFERENCES supplier(id));
CREATE TABLE IF NOT EXISTS sys_user(id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(64) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,role VARCHAR(16) NOT NULL,enabled INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS import_batch(id BIGINT AUTO_INCREMENT PRIMARY KEY,file_name VARCHAR(255),total INT DEFAULT 0,success INT DEFAULT 0,failed INT DEFAULT 0,skipped INT DEFAULT 0,status INT DEFAULT 0,errors TEXT,operator VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS review(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id BIGINT NOT NULL,content_raw VARCHAR(2000) NOT NULL,content_clean VARCHAR(2000),rating INT,review_time TIMESTAMP NOT NULL,source_type INT NOT NULL,batch_id BIGINT,dup_flag INT DEFAULT 0,mask_flag INT DEFAULT 0,FOREIGN KEY(product_id) REFERENCES product(id),FOREIGN KEY(batch_id) REFERENCES import_batch(id));
CREATE TABLE IF NOT EXISTS review_analysis(review_id BIGINT PRIMARY KEY,sentiment INT NOT NULL,confidence DOUBLE NOT NULL,fake_prob DOUBLE NOT NULL,fake_reason TEXT,aspects_json TEXT,model_version VARCHAR(64),FOREIGN KEY(review_id) REFERENCES review(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quality_index(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id BIGINT NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,qi DOUBLE NOT NULL,grade INT NOT NULL,dim_scores TEXT NOT NULL,sample_size INT,param_version VARCHAR(64),computed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,period_start,param_version),FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE IF NOT EXISTS param_snapshot(version VARCHAR(64) PRIMARY KEY,params_json TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rule_config(code VARCHAR(16) PRIMARY KEY,name VARCHAR(64),threshold_json TEXT NOT NULL,enabled INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS config_store(code VARCHAR(64) PRIMARY KEY,value_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alert(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id BIGINT NOT NULL,rule_code VARCHAR(32),level INT NOT NULL,metric_value DOUBLE,message TEXT,status INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,disposed_at TIMESTAMP,disposed_by VARCHAR(64),disposal_note VARCHAR(500));
CREATE TABLE IF NOT EXISTS mining_task(id BIGINT AUTO_INCREMENT PRIMARY KEY,scope_type INT,scope_value VARCHAR(64),params TEXT,status INT DEFAULT 0,progress INT DEFAULT 0,message TEXT,created_by VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,finished_at TIMESTAMP,cancelled INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor VARCHAR(64),action VARCHAR(64),detail TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
